SET FOREIGN_KEY_CHECKS=0;
CREATE DATABASE IF NOT EXISTS venomoncodb CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE venomoncodb;
DROP TABLE IF EXISTS curation_audit, ingestion_runs, structures, peptide_mechanisms, mechanisms, activity_assays, peptide_sources, cell_lines, peptides, publications, cancer_types, source_organisms;
CREATE TABLE source_organisms(organism_id INT AUTO_INCREMENT PRIMARY KEY,scientific_name VARCHAR(255) NOT NULL UNIQUE,common_name VARCHAR(255),venom_group ENUM('Snake','Scorpion','Spider','Cone snail','Unclassified') NOT NULL,taxonomy_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cancer_types(cancer_type_id INT AUTO_INCREMENT PRIMARY KEY,cancer_name VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE publications(publication_id INT AUTO_INCREMENT PRIMARY KEY,pmid VARCHAR(30) UNIQUE,doi VARCHAR(255) UNIQUE,title TEXT NOT NULL,journal VARCHAR(255),publication_year INT,authors TEXT,source_type ENUM('Primary research','Abstract','Database','Review','Controlled vocabulary') NOT NULL,source_url TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE peptides(peptide_id INT AUTO_INCREMENT PRIMARY KEY,public_id VARCHAR(30) NOT NULL UNIQUE,peptide_name VARCHAR(255) NOT NULL,sequence TEXT,sequence_length INT,uniprot_accession VARCHAR(50),sequence_source_status ENUM('UniProt verified','Primary paper verified','External database verified','Unavailable') DEFAULT 'Unavailable',curation_status ENUM('Curated','Partially curated','Needs review') DEFAULT 'Needs review',venom_verification_status ENUM('Verified','Needs review','Not established') DEFAULT 'Not established',biological_nature ENUM('Natural','Modified','Synthetic','Recombinant','Unknown') DEFAULT 'Unknown',primary_source_verified TINYINT(1) DEFAULT 0,source_traceability TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE peptide_sources(peptide_source_id INT AUTO_INCREMENT PRIMARY KEY,peptide_id INT NOT NULL,organism_id INT NOT NULL,source_description TEXT,publication_id INT NULL,FOREIGN KEY(peptide_id) REFERENCES peptides(peptide_id) ON DELETE CASCADE,FOREIGN KEY(organism_id) REFERENCES source_organisms(organism_id),FOREIGN KEY(publication_id) REFERENCES publications(publication_id));
CREATE TABLE cell_lines(cell_line_id INT AUTO_INCREMENT PRIMARY KEY,cell_line_name VARCHAR(100) NOT NULL,species VARCHAR(100),tissue_origin VARCHAR(255),cancer_type_id INT,FOREIGN KEY(cancer_type_id) REFERENCES cancer_types(cancer_type_id),UNIQUE(cell_line_name,species));
CREATE TABLE activity_assays(activity_id INT AUTO_INCREMENT PRIMARY KEY,peptide_id INT NOT NULL,cell_line_id INT NULL,publication_id INT NOT NULL,assay_method VARCHAR(255),exposure_time VARCHAR(100),endpoint_name VARCHAR(255),reported_value DECIMAL(15,6) NULL,reported_value_text VARCHAR(255),reported_unit VARCHAR(100) NULL,comparator_control TEXT,paper_location VARCHAR(255),curation_status ENUM('Curated','Partially curated','Needs review') DEFAULT 'Needs review',FOREIGN KEY(peptide_id) REFERENCES peptides(peptide_id) ON DELETE CASCADE,FOREIGN KEY(cell_line_id) REFERENCES cell_lines(cell_line_id),FOREIGN KEY(publication_id) REFERENCES publications(publication_id));
CREATE TABLE mechanisms(mechanism_id INT AUTO_INCREMENT PRIMARY KEY,mechanism_name VARCHAR(255) NOT NULL UNIQUE,description TEXT);
CREATE TABLE peptide_mechanisms(peptide_mechanism_id INT AUTO_INCREMENT PRIMARY KEY,peptide_id INT NOT NULL,mechanism_id INT NOT NULL,publication_id INT NOT NULL,cell_line_id INT NULL,evidence_method VARCHAR(255),evidence_statement TEXT,paper_location VARCHAR(255),curation_status ENUM('Curated','Partially curated','Needs review') DEFAULT 'Needs review',FOREIGN KEY(peptide_id) REFERENCES peptides(peptide_id) ON DELETE CASCADE,FOREIGN KEY(mechanism_id) REFERENCES mechanisms(mechanism_id),FOREIGN KEY(publication_id) REFERENCES publications(publication_id),FOREIGN KEY(cell_line_id) REFERENCES cell_lines(cell_line_id));
CREATE TABLE structures(structure_id INT AUTO_INCREMENT PRIMARY KEY,peptide_id INT NOT NULL,pdb_id VARCHAR(20) NOT NULL,polymer_entity VARCHAR(50),chain_id VARCHAR(20),experimental_method VARCHAR(255),resolution DECIMAL(8,3) NULL,sequence_match_status ENUM('Exact','Construct differs','Not assessed') DEFAULT 'Not assessed',rcsb_url VARCHAR(500),verification_date DATE,FOREIGN KEY(peptide_id) REFERENCES peptides(peptide_id) ON DELETE CASCADE,UNIQUE(peptide_id,pdb_id));
CREATE TABLE curation_audit(audit_id INT AUTO_INCREMENT PRIMARY KEY,table_name VARCHAR(100) NOT NULL,record_id INT NOT NULL,field_name VARCHAR(100),old_value TEXT,new_value TEXT,source_type VARCHAR(100),source_identifier VARCHAR(255),source_url TEXT,curator VARCHAR(255),curation_action VARCHAR(100),curation_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,notes TEXT);
CREATE TABLE ingestion_runs(run_id INT AUTO_INCREMENT PRIMARY KEY,source_name VARCHAR(255) NOT NULL,started_at DATETIME NOT NULL,finished_at DATETIME NULL,records_seen INT DEFAULT 0,records_imported INT DEFAULT 0,records_skipped INT DEFAULT 0,status VARCHAR(50),notes TEXT);
CREATE INDEX idx_peptide_name ON peptides(peptide_name);CREATE INDEX idx_activity_peptide ON activity_assays(peptide_id);CREATE INDEX idx_activity_cell ON activity_assays(cell_line_id);CREATE INDEX idx_mechanism_peptide ON peptide_mechanisms(peptide_id);CREATE INDEX idx_structure_pdb ON structures(pdb_id);CREATE FULLTEXT INDEX idx_peptide_search ON peptides(peptide_name,sequence);

SET FOREIGN_KEY_CHECKS=1;
